import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"乾","description":"周易集解 - 乾","frontmatter":{"title":"乾","description":"周易集解 - 乾"},"headers":[],"relativePath":"classics/jijie/001.md","filePath":"classics/jijie/001.md"}'),l={name:"classics/jijie/001.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="乾" tabindex="-1">乾 <a class="header-anchor" href="#乾" aria-label="Permalink to “乾”">​</a></h1><h2 id="乾-1" tabindex="-1">乾 <a class="header-anchor" href="#乾-1" aria-label="Permalink to “乾”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>乾，元享利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>案：《說卦》：「乾，健也。」言天之體以健為用，運行不息，應化無窮，故聖人則之。欲使人法天之用，不法天之體，故名乾，不名天也。</p><p>《子夏傳》曰：元，始也。亨，通也。利，和也。貞，正也。言乾稟純陽之性，故能首出庶物，各得元始、開通、和諧、貞固，不失其宜。是以君子法乾而行四德，故曰「元亨利貞」矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命。保合大和，乃利貞。首出庶物，萬國鹹寧。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>劉瓛曰：彖者，斷也，斷一卦之才也。</p><p>《九家易》曰：陽稱大。六爻純陽，故曰「大」。乾者純陽，眾卦所生，天之象也。觀乾之始，以知天德，惟天為大，惟乾則之，故曰「大哉」。元者，氣之始也。</p><p>荀爽曰：謂分為六十四卦，萬一千五百二十策，皆受始於乾也。策取始於乾，猶萬物之生稟於天。</p><p>《九家易》曰：乾之為德，乃統繼天道，與天合化也。</p><p>虞翻曰：已成既濟，上坎為雲，下坎為雨，故「雲行雨施」。乾以雲雨，流坤之形，萬物化成，故曰「品物流形」也。</p><p>荀爽曰：乾起坎，而終於離。坤起於離，而終於坎。離坎者，乾坤之家，而陰陽之府，故曰「大明終始」也。</p><p>荀爽曰：六爻隨時而成乾。</p><p>侯果曰：大明，日也。六位，天地四時也。六爻效彼而作也。大明以晝夜為終始，六位以相揭為時成。言乾乘六氣而陶冶變化，運四時而統御天地，故曰「時乘六龍以御天」也。故《乾鑿度》曰：「日月終始萬物」，是其義也。</p><p>劉瓛曰：陽氣為萬物之所始，故曰「首出庶物」。立君而天下皆寧，故曰「萬國鹹寧」也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天行健，君子以自強不息。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>案：象者，像也，取其法象卦爻之德。</p><p>何妥曰：天體不健，能行之德健也。猶如地體不順，承弱之勢順也。所以乾卦獨變名為健者。</p><p>宋衷曰：晝夜不懈，以健詳其名。餘卦各當名，不假於詳矣。</p><p>虞翻曰：君子謂三。乾健，故強。天一日一夜過週一度，故自強不息。老子曰：自勝者強。</p><p>乾寶曰：言君子通之於賢也。凡勉強以德，不必須在位也。故堯舜一日萬機，文王日昃不暇食，仲尼終夜不寢，顔子欲罷不能，自此以下，莫敢淫心捨力。故曰自強不息矣。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，潛龍勿用。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>崔憬曰：九者，老陽之數，動之所佔，故陽稱焉。潛，隱也。龍下隱地，潛德不彰，是以君子韜光待時，未成其行。故曰「勿用」。</p><p>《子夏傳》曰：龍，所以象陽也。</p><p>馬融曰：物莫大於龍，故借龍以喻天之陽氣也。初九，建子之月。陽氣始動於黃泉，既未萌牙，猶是潛伏，故曰「潛龍」也。</p><p>沉驎士曰：稱龍者，假像也。天地之氣有昇降，君子之道有行藏。龍之為物，能飛能潛，故借龍比君子之德也。初九既尚潛伏，故言「勿用」。</p><p>乾寶曰：位始，故稱初。陽重，故稱九。陽在初九，十一月之時，自復來也。初九，甲子天正之位，而乾元所始也。陽處三泉之下，聖德在愚俗之中，此文王在羑里之爻也。雖有聖明之德，未被時用，故曰「勿用」。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>潛龍勿用，陽在下也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：氣微位卑，雖有陽德，潛藏在下，故曰勿用也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，見龍在田，利見大人。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>王弼曰：出潛離隱，故曰「見龍」。處於地上，故曰「在田」。德施周普，居中不偏，雖非君位，君之德也。初則不彰，三則乾乾，四則或躍，上則過亢。利見大人，唯二五焉。</p><p>鄭玄曰：二於三才為地道，地上即田，故稱「田」也。</p><p>乾寶曰：陽在九二，十二月之時，自臨來也。二為地上，田在地之表，而有人功者也。陽氣將施，聖人將顯，此文王免於羑里之日也。故曰「利見大人」。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>見龍在田，德施普也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：見者，見居其位。田，謂坤也。二當升坤五。故曰「見龍在田」。大人，謂天子。見據尊位，臨長群陰，德施於下，故曰德施普也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，君子終日乾乾，夕惕若，厲，無咎。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>鄭玄曰：三於三才為人道。有乾德而在人道，君子之象。</p><p>虞翻曰：謂陽息至三，已變成離。離為日，坤為夕。</p><p>荀爽曰：日以喻君。謂三居下體之終，而為之君，承乾行乾，故曰「乾乾」。夕惕以喻臣。謂三臣於五，則疾修柔順，危去陽行，故曰「無咎」。</p><p>乾寶曰：爻以氣表，繇以龍興，嫌其不關人事，故著君子焉。陽在九三，正月之時，自泰來也。陽氣始出地上，而接動物。人為靈，故以人事成天地之功者，在於此爻焉。故君子以之憂深思遠，朝夕匪懈。仰憂嘉會之不序，俯懼義和之不逮。反覆天道，謀始反終。故曰「終日乾乾」。此蓋文王反國大釐其政之日也。凡無咎者，憂中之喜，善補過者也。文恨早耀，文明之德，以蒙大難，增修柔順，以懷多福，故曰「無咎」矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>終日乾乾，反覆道也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：至三體復，故反覆道，謂否泰反其類也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，或躍在淵，無咎。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>崔憬曰：言君子進德修業，欲及於時。猶龍自試躍天，疑而處淵。上下進退，非邪離群。故「無咎」。</p><p>乾寶曰：陽氣在四，二月之時，自大壯來也。四虛中也。躍者，暫起之言，既不安於地，而未能飛於天也。四以初為應。淵，謂初九甲子，龍之所由升也。或之者，疑之也。此武王舉兵孟津，觀釁而退之爻也。守柔順，則逆天人之應；通權道，則違經常之教。故聖人不得已而為之，故其辭疑矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>或躍在淵，進無咎也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：乾者，君卦。四者，陰位。故上躍居五者，欲下居坤初，求陽之正。地下稱淵也。陽道樂進，故曰進無咎也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，飛龍在天，利見大人。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>鄭玄曰：五於三才為天道。天者，清明無形，而龍在焉，飛之象也。</p><p>虞翻曰：謂四已變，則五體離。離為飛，五在天，故「飛龍在天，利見大人」也。謂若庖犧觀象於天，造作八卦，備物致用，以利天下，故曰「飛龍在天」。天下之所利見也。</p><p>乾寶曰：陽在九五，三月之時，自夬來也。五在天位，故曰「飛龍」。此武王克紂正位之爻也。聖功既就，萬物既覩，故曰「利見大人」矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>飛龍在天，大人造也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：飛者，喻無所拘。天者，首事造制。大人造法，見居天位，聖人作為萬物覩，是其義也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，亢龍有悔。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>王肅曰：窮高曰亢。知進忘退，故悔也。</p><p>乾寶曰：陽在上九，四月之時也。亢，過也。乾體既備，上位既終。天之鼓物，寒暑相報；聖人治世，威德相濟；武功既成，義在止戈。盈而不反，必陷於悔。</p><p>案：以人事明之，若桀放於南巢，湯有慚德，斯類是也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>亢龍有悔，盈不可久也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：陽當居五，今乃居上，故曰盈也。亢極失位，當下之坤三，故曰盈不可久，若太上皇者也。下之坤三，屈為諸侯，故曰悔者也。</p><h2 id="用九" tabindex="-1">用九 <a class="header-anchor" href="#用九" aria-label="Permalink to “用九”">​</a></h2><p>用九，見群龍無首，吉。</p><h2 id="用九注" tabindex="-1">用九注 <a class="header-anchor" href="#用九注" aria-label="Permalink to “用九注”">​</a></h2><p>劉瓛曰：總六爻純九之義，故曰「用九」也。</p><p>王弼曰：九，天之德也。能用天德，乃見群龍之義焉。夫以剛健而居人之首，則物之所不與也。以柔順而為不正，則佞邪之道也。故乾吉在無首，坤利在永貞矣。</p><h2 id="象-7" tabindex="-1">象 <a class="header-anchor" href="#象-7" aria-label="Permalink to “象”">​</a></h2><p>用九，天德不可為首也。</p><h2 id="象傳注-7" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-7" aria-label="Permalink to “象傳注”">​</a></h2><p>宋衷曰：用九，六位皆九，故曰見群龍。純陽則天德也。萬物之始，莫能先之，不可為首。先之者兇，隨之者吉，故曰無首，吉。</p>',98)])])}const f=e(l,[["render",p]]);export{b as __pageData,f as default};
